-- Stand-in for the one production table the base cdesc-machine harness does not build (shape read from production, 10 Nov 2026): the stored AI answer of a reading.
create table if not exists pipeline.enrich_ai_answers (
  id bigint generated by default as identity primary key,
  item_id bigint not null,
  attempts integer not null default 1,
  state text not null default 'recorded',
  answer jsonb,
  cost_usd numeric,
  received_at timestamptz not null default now(),
  settled_at timestamptz,
  evidence_id uuid,
  storage_path text,
  detail text,
  unique (item_id, attempts)
);
